import os
import re
import subprocess


def _detect_section(subject: str, body: str) -> str:
    text = (subject + " " + body).lower()
    if "chef" in text and "battle" in text:
        return "Chef Battles"
    if "recipe" in text:
        return "Recipes"
    if "article" in text:
        return "Articles"
    if "account" in text or "auth" in text or "login" in text:
        return "Accounts"
    if "newsfeed" in text or "news" in text:
        return "Newsfeed"
    if "sponsor" in text or "stripe" in text:
        return "Sponsors"
    if "migration" in text or "migrate" in text:
        return "Database"
    if "static" in text or "css" in text or "js" in text or "template" in text:
        return "Frontend"
    if "deploy" in text or "version" in text or "bump" in text:
        return "Deploy"
    if "test" in text:
        return "Tests"
    return "General"


def _parse_git_log(repo_path: str, limit: int = 60) -> list[dict]:
    try:
        raw = subprocess.check_output(
            ["git", "log", f"--max-count={limit}", "--format=%x00%H%x01%h%x01%ad%x01%s%x01%b", "--date=short"],
            cwd=repo_path,
            stderr=subprocess.DEVNULL,
            text=True,
        )
    except Exception:
        return []

    entries = []
    for block in raw.split("\x00"):
        block = block.strip()
        if not block:
            continue
        parts = block.split("\x01", 4)
        if len(parts) < 4:
            continue
        full_hash, short_hash, date, subject = parts[0], parts[1], parts[2], parts[3]
        body = parts[4].strip() if len(parts) == 5 else ""

        body_lines = [ln.rstrip() for ln in body.splitlines() if ln.strip()]
        checklist = [ln.lstrip("-• ") for ln in body_lines if ln.lstrip().startswith("-") or re.match(r"^CB-\d+", ln.lstrip())]
        summary_lines = [ln for ln in body_lines if not ln.lstrip().startswith("-") and not re.match(r"^CB-\d+", ln.lstrip()) and "Co-Authored-By" not in ln]
        summary = " ".join(summary_lines) if summary_lines else subject

        entries.append({
            "version": short_hash,
            "date": date,
            "commit": short_hash,
            "title": subject,
            "section": _detect_section(subject, body),
            "summary": summary,
            "checklist": checklist,
            "stats": [],
            "notes": "",
            "deployment_status": "Deployed",
        })

    return entries


def build_git_journal(repo_path: str, limit: int = 60) -> list[dict]:
    git_entries = _parse_git_log(repo_path, limit=limit)
    if not git_entries:
        return list(reversed(RELEASE_JOURNAL))
    return git_entries


_FOOTER_VERSION_RE = re.compile(r'class="footer-version">\s*v?([0-9]+(?:\.[0-9]+)+)')


def current_version(repo_path: str) -> str:
    """The version this checkout actually serves, read from the site footer.

    The footer in templates/base.html is bumped on every deploy and is what a
    visitor sees, so it is the one place that cannot drift from what shipped.

    RELEASE_JOURNAL is a hand-written highlight list. The build board used to
    take its header from RELEASE_JOURNAL[0] with a comment promising the header
    would "never go stale again" — and it went stale anyway, showing v2.5.589
    while production served v2.5.667, because nobody adds an entry per release
    and nothing made them. A number that depends on a person remembering is a
    number that will be wrong; this one is derived.

    Falls back to the journal's newest entry if the template cannot be read, so
    a missing file degrades to the old behaviour instead of an exception.
    """
    try:
        base_html = os.path.join(repo_path, "templates", "base.html")
        with open(base_html, encoding="utf-8") as handle:
            match = _FOOTER_VERSION_RE.search(handle.read())
        if match:
            return "v" + match.group(1)
    except Exception:
        pass
    return "v" + RELEASE_JOURNAL[0]["version"]
